WITH problems AS (SELECT 'missing_save_function'::text AS issue,'Khong tim thay save_inventory_stocktake_draft_v1'::text AS detail WHERE to_regprocedure('public.save_inventory_stocktake_draft_v1(uuid,date,text,jsonb)') IS NULL UNION ALL SELECT 'missing_cancel_function','Khong tim thay cancel_inventory_stocktake_draft_v1' WHERE to_regprocedure('public.cancel_inventory_stocktake_draft_v1(uuid)') IS NULL UNION ALL SELECT 'anon_can_execute_save','Vai tro anon van goi duoc ham luu nhap' WHERE COALESCE(has_function_privilege('anon',to_regprocedure('public.save_inventory_stocktake_draft_v1(uuid,date,text,jsonb)'),'EXECUTE'),false) UNION ALL SELECT 'anon_can_execute_cancel','Vai tro anon van goi duoc ham huy nhap' WHERE COALESCE(has_function_privilege('anon',to_regprocedure('public.cancel_inventory_stocktake_draft_v1(uuid)'),'EXECUTE'),false) UNION ALL SELECT 'authenticated_cannot_execute_save','Tai khoan dang nhap khong goi duoc ham luu nhap' WHERE to_regprocedure('public.save_inventory_stocktake_draft_v1(uuid,date,text,jsonb)') IS NOT NULL AND NOT COALESCE(has_function_privilege('authenticated',to_regprocedure('public.save_inventory_stocktake_draft_v1(uuid,date,text,jsonb)'),'EXECUTE'),false) UNION ALL SELECT 'authenticated_cannot_execute_cancel','Tai khoan dang nhap khong goi duoc ham huy nhap' WHERE to_regprocedure('public.cancel_inventory_stocktake_draft_v1(uuid)') IS NOT NULL AND NOT COALESCE(has_function_privilege('authenticated',to_regprocedure('public.cancel_inventory_stocktake_draft_v1(uuid)'),'EXECUTE'),false) UNION ALL SELECT 'cancel_missing_admin_guard','Ham huy nhap thieu hang rao Admin/Super Admin' WHERE COALESCE(pg_get_functiondef(to_regprocedure('public.cancel_inventory_stocktake_draft_v1(uuid)')),'') NOT ILIKE '%public.is_admin()%' UNION ALL SELECT 'cancel_missing_draft_guard','Ham huy nhap thieu hang rao chi cho ban nhap' WHERE COALESCE(pg_get_functiondef(to_regprocedure('public.cancel_inventory_stocktake_draft_v1(uuid)')),'') NOT ILIKE '%v_status<>''draft''%' UNION ALL SELECT 'save_missing_manager_guard','Ham luu nhap thieu hang rao Manager/Admin' WHERE COALESCE(pg_get_functiondef(to_regprocedure('public.save_inventory_stocktake_draft_v1(uuid,date,text,jsonb)')),'') NOT ILIKE '%public.is_manager()%' UNION ALL SELECT 'draft_has_inventory_effect','Phieu nhap '||st.id::text||' dang co giao dich hoac moc ton active' FROM public.inventory_stocktakes st WHERE st.status='draft' AND st.deleted_at IS NULL AND (EXISTS(SELECT 1 FROM public.inventory_transactions t WHERE t.stocktake_id=st.id AND t.deleted_at IS NULL) OR EXISTS(SELECT 1 FROM public.inventory_opening_balances ob WHERE ob.source_stocktake_id=st.id AND ob.deleted_at IS NULL))) SELECT issue,detail FROM problems ORDER BY issue;
